ALTER TABLE fs_employees ADD COLUMN second_surname TEXT NOT NULL DEFAULT '';
ALTER TABLE fs_employees ADD COLUMN first_name TEXT NOT NULL DEFAULT '';
ALTER TABLE fs_employees ADD COLUMN other_names TEXT NOT NULL DEFAULT '';
ALTER TABLE fs_employees ADD COLUMN name_parts_confirmed_at TEXT;

